import java.util.Locale;

public class Estimator {

    /** All inputs are assumptions supplied by the caller. */
    record Workload(String name, double dau, double writesPerUserDay, double readsPerUserDay,
                    double bytesPerWrite, double bytesPerRead, double retentionYears,
                    double peakFactor, double cacheShare, double replication) { }

    static final double SECONDS_PER_DAY = 86_400;

    static String bytes(double v) {
        String[] unit = {"B", "KB", "MB", "GB", "TB", "PB"};
        int i = 0;
        while (v >= 1000 && i < unit.length - 1) { v /= 1000; i++; }
        return String.format(Locale.ROOT, "%.1f %s", v, unit[i]);
    }

    static String bits(double v) {
        String[] unit = {"bit/s", "Kbit/s", "Mbit/s", "Gbit/s", "Tbit/s"};
        int i = 0;
        while (v >= 1000 && i < unit.length - 1) { v /= 1000; i++; }
        return String.format(Locale.ROOT, "%.1f %s", v, unit[i]);
    }

    static String rate(double v) {
        if (v >= 1e3) return String.format(Locale.ROOT, "%.1f K/s", v / 1e3);
        return String.format(Locale.ROOT, "%.1f /s", v);
    }

    static void line(String label, String value) {
        System.out.printf(Locale.ROOT, "%-24s: %s%n", label, value);
    }

    static void report(Workload w) {
        double writesDay = w.dau() * w.writesPerUserDay();
        double readsDay = w.dau() * w.readsPerUserDay();
        double avgWrite = writesDay / SECONDS_PER_DAY, avgRead = readsDay / SECONDS_PER_DAY;
        double peakWrite = avgWrite * w.peakFactor(), peakRead = avgRead * w.peakFactor();
        double storageDay = writesDay * w.bytesPerWrite();
        double storageTotal = storageDay * 365 * w.retentionYears() * w.replication();
        System.out.println("== " + w.name() + " ==");
        line("writes per day", String.format(Locale.ROOT, "%,.0f", writesDay));
        line("reads per day", String.format(Locale.ROOT, "%,.0f", readsDay));
        line("write rate avg / peak", rate(avgWrite) + " / " + rate(peakWrite));
        line("read rate avg / peak", rate(avgRead) + " / " + rate(peakRead));
        line("read : write", String.format(Locale.ROOT, "%.0f : 1", readsDay / writesDay));
        line("new data per day", bytes(storageDay));
        line("total storage", bytes(storageTotal) + " (" + w.retentionYears() + " years, x"
                + w.replication() + " replicas)");
        line("peak ingress", bits(peakWrite * w.bytesPerWrite() * 8));
        line("peak egress", bits(peakRead * w.bytesPerRead() * 8));
        line("cache (" + (int) (w.cacheShare() * 100) + "% of read bytes)",
                bytes(readsDay * w.bytesPerRead() * w.cacheShare()));
        System.out.println();
    }

    public static void main(String[] args) {
        // name, DAU, writes/user/day, reads/user/day, B/write, B/read, years, peak, cache, replicas
        report(new Workload("URL shortener", 100e6, 0.1, 10, 500, 500, 5, 3, 0.2, 3));
        report(new Workload("Social timeline", 200e6, 2, 100, 300, 1_000, 5, 2, 0.2, 3));
        report(new Workload("Video streaming", 50e6, 0.002, 5, 300e6, 50e6, 5, 2, 0.02, 1.5));
    }
}

import java.util.Arrays;
import java.util.Locale;
import java.util.Random;

public class TailAmplification {

    // One backend call: lognormal body (median 10 ms) plus a 1 % chance of a 100-300 ms stall.
    static double call(Random r) {
        double ms = Math.exp(Math.log(10) + 0.4 * r.nextGaussian());
        if (r.nextDouble() < 0.01) {
            ms += 100 + 200 * r.nextDouble();
        }
        return ms;
    }

    static double pct(double[] sorted, double p) {
        return sorted[(int) Math.min(sorted.length - 1, Math.ceil(p * sorted.length) - 1)];
    }

    public static void main(String[] args) {
        Random r = new Random(42);
        int trials = 200_000;
        System.out.println("fan-out | p50 ms | p99 ms | p99.9 ms | P(slow call): sim / formula");
        for (int n : new int[] {1, 5, 10, 50, 100, 500}) {
            double[] lat = new double[trials];
            int slow = 0;
            for (int t = 0; t < trials; t++) {
                double max = 0;
                boolean anySlow = false;
                for (int i = 0; i < n; i++) {
                    double c = call(r);
                    if (c > 100) anySlow = true;
                    max = Math.max(max, c);
                }
                lat[t] = max;
                if (anySlow) slow++;
            }
            Arrays.sort(lat);
            System.out.printf(Locale.ROOT, "%7d | %6.1f | %6.1f | %8.1f | %.3f / %.3f%n",
                    n, pct(lat, 0.50), pct(lat, 0.99), pct(lat, 0.999),
                    slow / (double) trials, 1 - Math.pow(0.99, n));
        }
    }
}

import java.util.Arrays;
import java.util.Locale;
import java.util.Random;

public class QueueSim {

    public static void main(String[] args) {
        double serviceMs = 10.0;            // mean service time, exponential
        int n = 2_000_000;
        System.out.println("M/M/1 queue, mean service 10 ms (capacity 100 req/s)");
        System.out.println("util | mean ms sim / theory | p99 ms sim / theory | L sim / theory");
        for (double rho : new double[] {0.50, 0.70, 0.80, 0.90, 0.95, 0.99}) {
            Random r = new Random(7);
            double lambda = rho / serviceMs;          // arrivals per ms
            double[] resp = new double[n];
            double wait = 0;                           // Lindley recursion
            double totalResp = 0;
            for (int i = 0; i < n; i++) {
                double service = -serviceMs * Math.log(1 - r.nextDouble());
                double interarrival = -Math.log(1 - r.nextDouble()) / lambda;
                resp[i] = wait + service;
                totalResp += resp[i];
                wait = Math.max(0, wait + service - interarrival);
            }
            Arrays.sort(resp);
            double mean = totalResp / n;
            double p99 = resp[(int) (0.99 * n)];
            double theoryMean = serviceMs / (1 - rho);
            double theoryP99 = theoryMean * Math.log(100);
            // Little's law: average number in system L = lambda * W
            double lSim = lambda * mean;
            double lTheory = rho / (1 - rho);
            System.out.println(String.format(Locale.ROOT,
                    "%.2f | %7.1f / %7.1f      | %7.1f / %7.1f     | %6.2f / %6.2f",
                    rho, mean, theoryMean, p99, theoryP99, lSim, lTheory));
        }
        System.out.println();
        System.out.println("Amdahl: speedup = 1 / ((1 - p) + p / n)");
        System.out.println("parallel fraction p | n=2 | n=8 | n=32 | n=128 | limit 1/(1-p)");
        for (double p : new double[] {0.50, 0.90, 0.95, 0.99}) {
            StringBuilder sb = new StringBuilder(String.format(Locale.ROOT, "%19.2f", p));
            for (int cores : new int[] {2, 8, 32, 128}) {
                sb.append(String.format(Locale.ROOT, " | %5.2f", 1 / ((1 - p) + p / cores)));
            }
            sb.append(String.format(Locale.ROOT, " | %5.1f", 1 / (1 - p)));
            System.out.println(sb);
        }
    }
}

import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Locale;
import java.util.Random;
import java.util.TreeMap;
import java.util.function.IntSupplier;

public class LbSim {

    static final int BACKENDS = 10;
    static final int REQUESTS = 400_000;
    static final int KEYS = 10_000;

    /** One FIFO single-server queue per backend; in-flight = requests not yet completed. */
    static class Backend {
        final double speed;            // service-time multiplier
        double freeAt = 0;
        long served = 0;
        final ArrayDeque<Double> completions = new ArrayDeque<>();
        Backend(double speed) { this.speed = speed; }
        int inFlight(double now) {
            while (!completions.isEmpty() && completions.peekFirst() <= now) {
                completions.pollFirst();
            }
            return completions.size();
        }
        double submit(double now, double service) {
            double start = Math.max(now, freeAt);
            freeAt = start + service * speed;
            completions.addLast(freeAt);
            served++;
            return freeAt - now;       // response time
        }
    }

    static int zipfKey(Random r, double[] cdf) {
        double u = r.nextDouble();
        int lo = 0, hi = cdf.length - 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (cdf[mid] < u) lo = mid + 1; else hi = mid;
        }
        return lo;
    }

    static long mix(long x) {
        x ^= x >>> 33; x *= 0xff51afd7ed558ccdL;
        x ^= x >>> 33; x *= 0xc4ceb9fe1a85ec53L;
        x ^= x >>> 33;
        return x;
    }
    static TreeMap<Long, Integer> ring(int vnodes) {
        TreeMap<Long, Integer> ring = new TreeMap<>();
        for (int b = 0; b < BACKENDS; b++)
            for (int v = 0; v < vnodes; v++) ring.put(mix(b * 1_000_003L + v), b);
        return ring;
    }

    static void run(String scenario, double ratePerSec, double slowFactor) {
        System.out.println("-- " + scenario);
        System.out.println("algorithm              | max/mean load | p50 ms | p99 ms | node 0");
        double[] cdf = new double[KEYS];
        double sum = 0;
        for (int i = 0; i < KEYS; i++) { sum += 1.0 / (i + 1); cdf[i] = sum; }
        for (int i = 0; i < KEYS; i++) cdf[i] /= sum;
        TreeMap<Long, Integer> ring = ring(150);
        for (String algo : new String[] {"round robin", "random", "least connections",
                "power of two choices", "consistent hash (zipf)"}) {
            Random r = new Random(11);
            Backend[] bs = new Backend[BACKENDS];
            for (int i = 0; i < BACKENDS; i++) bs[i] = new Backend(i == 0 ? slowFactor : 1.0);
            double[] resp = new double[REQUESTS];
            double now = 0;
            int rr = 0;
            for (int q = 0; q < REQUESTS; q++) {
                now += -1000.0 / ratePerSec * Math.log(1 - r.nextDouble());       // ms
                // lognormal service time, median 8 ms, mean about 11 ms
                double service = Math.exp(Math.log(8.0) + 0.8 * r.nextGaussian());
                final double t = now;
                int pick;
                switch (algo) {
                    case "round robin" -> pick = rr++ % BACKENDS;
                    case "random" -> pick = r.nextInt(BACKENDS);
                    case "least connections" -> {
                        int start = r.nextInt(BACKENDS);
                        pick = start;
                        for (int k = 1; k < BACKENDS; k++) {
                            int i = (start + k) % BACKENDS;
                            if (bs[i].inFlight(t) < bs[pick].inFlight(t)) pick = i;
                        }
                    }
                    case "power of two choices" -> {
                        int a = r.nextInt(BACKENDS), b = r.nextInt(BACKENDS);
                        pick = bs[a].inFlight(t) <= bs[b].inFlight(t) ? a : b;
                    }
                    default -> {
                        long h = mix(zipfKey(r, cdf) * 7919L + 13);
                        var e = ring.ceilingEntry(h);
                        pick = (e != null ? e : ring.firstEntry()).getValue();
                    }
                }
                resp[q] = bs[pick].submit(t, service);
            }
            long max = 0, tot = 0;
            for (Backend b : bs) { max = Math.max(max, b.served); tot += b.served; }
            if (algo.startsWith("consistent")) {
                StringBuilder sb = new StringBuilder("   per-node share of requests (%):");
                for (Backend b : bs) {
                    sb.append(String.format(Locale.ROOT, " %.1f", 100.0 * b.served / tot));
                }
                System.out.println(sb);
            }
            Arrays.sort(resp);
            System.out.printf(Locale.ROOT, "%-22s | %13.2f | %6.1f | %6.1f | %5.1f%%%n",
                    algo, max / (tot / (double) BACKENDS), resp[REQUESTS / 2],
                    resp[(int) (0.99 * REQUESTS)], 100.0 * bs[0].served / tot);
        }
        System.out.println();
    }

    public static void main(String[] args) {
        run("A: 10 equal nodes, 700 req/s (capacity about 900 req/s)", 700, 1.0);
        run("B: node 0 runs 3x slower, 500 req/s", 500, 3.0);
    }
}

import java.util.Locale;
import java.util.TreeMap;

public class RemapDemo {

    static long mix(long x) {
        x ^= x >>> 33; x *= 0xff51afd7ed558ccdL;
        x ^= x >>> 33; x *= 0xc4ceb9fe1a85ec53L;
        x ^= x >>> 33;
        return x;
    }

    static TreeMap<Long, Integer> ring(int nodes, int vnodes) {
        TreeMap<Long, Integer> ring = new TreeMap<>();
        for (int n = 0; n < nodes; n++) {
            for (int v = 0; v < vnodes; v++) ring.put(mix(n * 1_000_003L + v), n);
        }
        return ring;
    }

    static int owner(TreeMap<Long, Integer> ring, long key) {
        var e = ring.ceilingEntry(mix(key * 7919L + 13));
        return (e != null ? e : ring.firstEntry()).getValue();
    }

    public static void main(String[] args) {
        int keys = 200_000;
        for (int n : new int[] {5, 10, 20}) {
            int movedMod = 0, movedRing = 0;
            var before = ring(n, 150);
            var after = ring(n + 1, 150);
            for (long k = 0; k < keys; k++) {
                if (Math.floorMod(mix(k), n) != Math.floorMod(mix(k), n + 1)) movedMod++;
                if (owner(before, k) != owner(after, k)) movedRing++;
            }
            String fmt = "%2d -> %2d nodes: mod N %5.1f%%, ring %5.1f%%, ideal %.1f%%%n";
            System.out.printf(Locale.ROOT, fmt,
                    n, n + 1, 100.0 * movedMod / keys, 100.0 * movedRing / keys, 100.0 / (n + 1));
        }
    }
}

import java.util.Locale;
import java.util.Random;

public class Availability {

    static final int MINUTES = 525_600;      // one year in one-minute slots
    static final int YEARS = 60;             // independent simulated years per topology

    /** Decides from the component states (and a shared zone) whether the service is up. */
    interface Topology { boolean up(boolean[] c, boolean zoneDown, Random r); }

    static void simulate(String name, int components, double a, double zoneDown,
                         Topology topology, double formula) {
        Random r = new Random(5);
        boolean[] c = new boolean[components];
        long up = 0, total = (long) MINUTES * YEARS;
        for (long m = 0; m < total; m++) {
            for (int i = 0; i < components; i++) c[i] = r.nextDouble() < a;
            boolean zone = zoneDown > 0 && r.nextDouble() < zoneDown;
            if (topology.up(c, zone, r)) up++;
        }
        double availability = up / (double) total;
        System.out.printf(Locale.ROOT, "%-40s | %9.5f%% | %9.5f%% | %8.1f%n", name,
                100 * availability, 100 * formula, (1 - availability) * MINUTES);
    }

    public static void main(String[] args) {
        String h = "%-40s | %-10s | %-10s | %s%n";
        System.out.printf(h, "topology", "simulated", "formula", "min/yr");
        simulate("1 component, 0.999", 1, 0.999, 0, (c, z, r) -> c[0], 0.999);
        simulate("5 in series, each 0.999", 5, 0.999, 0,
                (c, z, r) -> c[0] && c[1] && c[2] && c[3] && c[4], Math.pow(0.999, 5));
        simulate("10 in series, each 0.999", 10, 0.999, 0, (c, z, r) -> {
            for (boolean b : c) if (!b) return false;
            return true;
        }, Math.pow(0.999, 10));
        simulate("2 parallel, each 0.99, independent", 2, 0.99, 0,
                (c, z, r) -> c[0] || c[1], 1 - Math.pow(0.01, 2));
        simulate("3 parallel, each 0.99, independent", 3, 0.99, 0,
                (c, z, r) -> c[0] || c[1] || c[2], 1 - Math.pow(0.01, 3));
        // both replicas share one zone that is down 0.1 % of the time (common-cause failure)
        simulate("2 parallel 0.99 in one zone (0.999)", 2, 0.99, 0.001,
                (c, z, r) -> !z && (c[0] || c[1]), 0.999 * (1 - Math.pow(0.01, 2)));
        // load balancer 0.9999, then two parallel app servers 0.99, then database 0.999
        simulate("LB 0.9999 -> 2 app 0.99 -> DB 0.999", 2, 0.99, 0,
                (c, z, r) -> r.nextDouble() < 0.9999 && (c[0] || c[1])
                        && r.nextDouble() < 0.999,
                0.9999 * (1 - 0.0001) * 0.999);
    }
}

import java.util.Locale;
import java.util.Random;

public class RetryStorm {

    static final int TICKS = 40;                       // one tick = one second
    static final int OUTAGE_START = 10, OUTAGE_END = 15;   // capacity is 0 in ticks 10..14
    static final double CAPACITY = 1000, NEW_LOAD = 800;
    static final int MAX_ATTEMPTS = 5;

    /** pending[t][k]: requests whose k-th attempt (k = 0 is the first try) happens in tick t. */
    static double[] simulate(boolean backoff, boolean budget, Random rnd, double[] offered) {
        double[][] pending = new double[TICKS + 64][MAX_ATTEMPTS];
        double[] served = new double[TICKS];
        for (int t = 0; t < TICKS; t++) {
            pending[t][0] += NEW_LOAD;
            double total = 0;
            for (double v : pending[t]) total += v;
            offered[t] = total;
            double cap = (t >= OUTAGE_START && t < OUTAGE_END) ? 0 : CAPACITY;
            double fraction = total == 0 ? 1 : Math.min(1, cap / total);
            served[t] = total * fraction;
            double retryBudget = budget ? 0.10 * NEW_LOAD : Double.MAX_VALUE;  // retries per tick
            for (int k = 0; k < MAX_ATTEMPTS - 1; k++) {
                double failed = pending[t][k] * (1 - fraction);
                double allowed = Math.min(failed, retryBudget);
                retryBudget -= allowed;
                if (allowed <= 0) continue;
                if (!backoff) {
                    pending[t + 1][k + 1] += allowed;          // immediate retry in the next tick
                } else {
                    int window = (int) Math.pow(2, k + 1);       // exponential window, full jitter
                    for (int i = 0; i < 100; i++) {
                        pending[t + 1 + rnd.nextInt(window)][k + 1] += allowed / 100;
                    }
                }
            }
        }
        return served;
    }

    public static void main(String[] args) {
        System.out.println("capacity 1000/s, new load 800/s, outage in ticks 10-14, 5 attempts");
        double[][] off = new double[3][TICKS];
        double[][] srv = new double[3][];
        boolean[] backoff = {false, true, true};
        boolean[] budget = {false, false, true};
        for (int i = 0; i < 3; i++) srv[i] = simulate(backoff[i], budget[i], new Random(1), off[i]);
        System.out.println("tick | immediate retry | backoff+jitter | backoff+jitter+budget");
        System.out.println("     | offered/served  | offered/served | offered/served");
        for (int t = 8; t < 30; t++) {
            System.out.printf(Locale.ROOT, "%4d | %7.0f/%6.0f | %7.0f/%6.0f | %7.0f/%6.0f%n", t,
                    off[0][t], srv[0][t], off[1][t], srv[1][t], off[2][t], srv[2][t]);
        }
        String[] names = {"immediate retry", "backoff+jitter", "backoff+jitter+budget"};
        for (int i = 0; i < 3; i++) {
            double peak = 0, extra = 0;
            for (int t = OUTAGE_END; t < TICKS; t++) {
                peak = Math.max(peak, off[i][t]);
                extra += Math.max(0, off[i][t] - NEW_LOAD);
            }
            System.out.printf(Locale.ROOT, "%-22s peak %.0f/s (%.2fx), extra requests %.0f%n",
                    names[i], peak, peak / NEW_LOAD, extra);
        }
    }
}

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Random;

public class LruDemo {
    /** LRU cache: a LinkedHashMap in access order evicts the eldest entry past capacity. */
    static final class LruCache<K, V> extends LinkedHashMap<K, V> {
        private final int capacity;

        LruCache(int capacity) {
            super(16, 0.75f, true);          // accessOrder = true
            this.capacity = capacity;
        }

        @Override
        protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
            return size() > capacity;
        }
    }

    /** Draws a key rank from a Zipf distribution using the cumulative distribution. */
    static int zipfKey(Random rnd, double[] cdf) {
        double u = rnd.nextDouble();
        int lo = 0, hi = cdf.length - 1;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (cdf[mid] < u) lo = mid + 1; else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) {
        int keys = 100_000, requests = 1_000_000;
        double[] cdf = new double[keys];
        double sum = 0;
        for (int i = 0; i < keys; i++) { sum += 1.0 / (i + 1); cdf[i] = sum; }   // Zipf, s = 1
        for (int i = 0; i < keys; i++) cdf[i] /= sum;

        System.out.println("keys=" + keys + " requests=" + requests + " zipf s=1.0");
        System.out.println("cache size (% of keys) | LRU hit ratio");
        for (double pct : new double[] {0.5, 1, 2, 5, 10, 20}) {
            int cap = (int) (keys * pct / 100.0);
            LruCache<Integer, Integer> cache = new LruCache<>(cap);
            Random rnd = new Random(42);
            long hits = 0;
            for (int i = 0; i < requests; i++) {
                int k = zipfKey(rnd, cdf);
                if (cache.get(k) != null) hits++; else cache.put(k, k);
            }
            System.out.printf("%6.1f%% (%6d entries) | %.1f%%%n",
                    pct, cap, 100.0 * hits / requests);
        }
        LruCache<Integer, Integer> cache = new LruCache<>(keys / 5);   // uniform keys, 20% cache
        Random rnd = new Random(42);
        long hits = 0;
        for (int i = 0; i < requests; i++) {
            int k = rnd.nextInt(keys);
            if (cache.get(k) != null) hits++; else cache.put(k, k);
        }
        System.out.printf("uniform keys, 20%% cache: %.1f%%%n", 100.0 * hits / requests);
    }
}

import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Function;

public class StampedeDemo {
    static final AtomicInteger dbLoads = new AtomicInteger();

    static String loadFromDb(String key) {
        dbLoads.incrementAndGet();
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return "value-of-" + key;
    }

    // Naive cache-aside: every thread that observes a miss loads from the database.
    static final ConcurrentHashMap<String, String> naive = new ConcurrentHashMap<>();

    static String naiveGet(String key) {
        String v = naive.get(key);
        if (v == null) { v = loadFromDb(key); naive.put(key, v); }
        return v;
    }

    // Single flight: concurrent misses for one key share one in-flight load.
    static final ConcurrentHashMap<String, CompletableFuture<String>> inflight =
            new ConcurrentHashMap<>();
    static final ConcurrentHashMap<String, String> guarded = new ConcurrentHashMap<>();

    static String singleFlightGet(String key) {
        String v = guarded.get(key);
        if (v != null) return v;
        CompletableFuture<String> mine = new CompletableFuture<>();
        CompletableFuture<String> existing = inflight.putIfAbsent(key, mine);
        if (existing != null) return existing.join();       // wait for the leader's load
        try {
            v = loadFromDb(key);
            guarded.put(key, v);
            mine.complete(v);
            return v;
        } finally {
            inflight.remove(key);
        }
    }

    static int run(Function<String, String> getter) throws Exception {
        dbLoads.set(0);
        int threads = 200;
        ExecutorService pool = Executors.newFixedThreadPool(threads);
        CountDownLatch start = new CountDownLatch(1), done = new CountDownLatch(threads);
        for (int i = 0; i < threads; i++) {
            pool.submit(() -> {
                try { start.await(); getter.apply("hot-key"); } catch (InterruptedException e) { }
                done.countDown();
            });
        }
        start.countDown();
        done.await();
        pool.shutdown();
        return dbLoads.get();
    }

    public static void main(String[] args) throws Exception {
        System.out.println("200 concurrent requests for one expired key, database latency 100 ms");
        System.out.println("naive cache-aside   : database loads = "
                + run(StampedeDemo::naiveGet));
