import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;

public class RingDemo {
    static long hash(String s) throws Exception {
        byte[] d = MessageDigest.getInstance("MD5").digest(s.getBytes(StandardCharsets.UTF_8));
        long h = 0;
        for (int i = 0; i < 8; i++) h = (h << 8) | (d[i] & 0xff);
        return h;
    }

    static TreeMap<Long, String> build(List<String> nodes, int vnodes) throws Exception {
        TreeMap<Long, String> ring = new TreeMap<>();
        for (String n : nodes)
            for (int v = 0; v < vnodes; v++) ring.put(hash(n + "#" + v), n);
        return ring;
    }

    static String owner(TreeMap<Long, String> ring, long h) {
        Map.Entry<Long, String> e = ring.ceilingEntry(h);
        return (e != null ? e : ring.firstEntry()).getValue();
    }

    public static void main(String[] args) throws Exception {
        int keys = 100_000;
        long[] keyHash = new long[keys];
        for (int i = 0; i < keys; i++) keyHash[i] = hash("user:" + i);
        List<String> nodes = new ArrayList<>();
        for (int i = 0; i < 10; i++) nodes.add("node" + i);

        System.out.println("10 nodes, 100000 keys, ideal load per node = 10000");
        System.out.println("vnodes/node | min    max    max/ideal | stddev/mean");
        for (int vn : new int[] {1, 10, 100, 500}) {
            TreeMap<Long, String> ring = build(nodes, vn);
            Map<String, Integer> load = new HashMap<>();
            for (long h : keyHash) load.merge(owner(ring, h), 1, Integer::sum);
            int min = Integer.MAX_VALUE, max = 0;
            double mean = keys / 10.0, var = 0;
            for (String n : nodes) {
                int c = load.getOrDefault(n, 0);
                min = Math.min(min, c); max = Math.max(max, c);
                var += (c - mean) * (c - mean);
            }
            System.out.printf("%11d | %-6d %-6d %-9.2f | %.1f%%%n", vn, min, max, max / mean,
                    100 * Math.sqrt(var / 10) / mean);
        }

        // keys moved when node count changes from 10 to 11
        TreeMap<Long, String> before = build(nodes, 100);
        List<String> more = new ArrayList<>(nodes); more.add("node10");
        TreeMap<Long, String> after = build(more, 100);
        int moved = 0, movedMod = 0;
        for (long h : keyHash) {
            if (!owner(before, h).equals(owner(after, h))) moved++;
            if (Long.remainderUnsigned(h, 10) != Long.remainderUnsigned(h, 11)) movedMod++;
        }
        System.out.println("\nadding an 11th node to 10 nodes:");
        System.out.printf("ring, 100 vnodes: %d keys move (%.1f%%); ideal 1/11 = 9.1%%%n",
                moved, 100.0 * moved / keys);
        System.out.printf("hash mod N: %d keys move (%.1f%%)%n",
                movedMod, 100.0 * movedMod / keys);
    }
}

