import random

random.seed(9)


class Cluster:
    """One leader and two followers; asynchronous replication with random lag (ms)."""

    def __init__(self, lag):
        self.lag, self.leader, self.fol, self.pending = lag, {}, [{}, {}], []

    def write(self, t, key, value):
        self.leader[key] = (value, t)
        for i in range(2):
            self.pending.append((t + random.randint(*self.lag), i, key, (value, t)))

    def tick(self, t):
        keep = []
        for due, i, key, val in self.pending:
            if due <= t:
                if key not in self.fol[i] or self.fol[i][key][1] <= val[1]:
                    self.fol[i][key] = val
            else:
                keep.append((due, i, key, val))
        self.pending = keep


def trial(policy):
    c, stale, reads, last_write = Cluster((5, 400)), 0, 0, None
    for t in range(2000):
        c.tick(t)
        if t % 100 == 0:                              # the user updates the profile
            c.write(t, "profile", f"v{t}")
            last_write = t
        if t % 50 == 25 and last_write is not None:   # the same user reads the profile
            reads += 1
            if policy == "random follower":
                src = c.fol[random.randrange(2)]
            elif policy == "leader for 500 ms after own write":
                src = c.leader if t - last_write < 500 else c.fol[random.randrange(2)]
            else:
                src = c.leader
            v = src.get("profile")
            if v is None or v[1] < last_write:
                stale += 1
    return stale, reads


for p in ["random follower", "leader for 500 ms after own write", "always leader"]:
    s, r = trial(p)
    print(f"{p:36s} stale reads of own write: {s:2d} of {r}")

import java.time.Instant;
import java.util.function.LongSupplier;

public class Snowflake {
    static final long EPOCH = 1_735_689_600_000L;       // 2025-01-01T00:00:00Z
    static final int NODE_BITS = 10, SEQ_BITS = 12;
    static final long MAX_SEQ = (1L << SEQ_BITS) - 1;

    private final long nodeId;
    private final LongSupplier clock;
    private long lastMs = -1, seq = 0;

    Snowflake(long nodeId, LongSupplier clock) {
        if (nodeId < 0 || nodeId >= (1L << NODE_BITS)) {
            throw new IllegalArgumentException("node id out of range");
        }
        this.nodeId = nodeId;
        this.clock = clock;
    }

    synchronized long next() {
        long now = clock.getAsLong();
        if (now < lastMs) {                              // refuse to go backwards
            throw new IllegalStateException("clock moved backwards by " + (lastMs - now) + " ms");
        }
        if (now == lastMs) {
            seq = (seq + 1) & MAX_SEQ;
            if (seq == 0) {                              // 4096 ids used: wait for the next ms
                while ((now = clock.getAsLong()) <= lastMs) { }
            }
        } else {
            seq = 0;
        }
        lastMs = now;
        return ((now - EPOCH) << (NODE_BITS + SEQ_BITS)) | (nodeId << SEQ_BITS) | seq;
    }

    static String decode(long id) {
        long ts = (id >>> (NODE_BITS + SEQ_BITS)) + EPOCH;
        long node = (id >>> SEQ_BITS) & ((1L << NODE_BITS) - 1);
        return Instant.ofEpochMilli(ts) + " node=" + node + " seq=" + (id & MAX_SEQ);
    }

    public static void main(String[] args) {
        Snowflake g = new Snowflake(7, System::currentTimeMillis);
        for (int i = 0; i < 3; i++) {
            long id = g.next();
            System.out.println(id + "  " + decode(id));
        }
        int n = 4_000_000;
        long[] ids = new long[n];
        long t0 = System.nanoTime();
        for (int i = 0; i < n; i++) ids[i] = g.next();
        double secs = (System.nanoTime() - t0) / 1e9;
        boolean sorted = true;
        for (int i = 1; i < n && sorted; i++) sorted = ids[i] > ids[i - 1];
        System.out.printf("%d ids in %.2f s (%.0f ids/s), strictly increasing: %b%n",
                n, secs, n / secs, sorted);

        long[] t = {1_000_000L + EPOCH};                 // controllable clock
        Snowflake skewed = new Snowflake(1, () -> t[0]);
        skewed.next();
        t[0] -= 5;                                       // the clock is stepped back by 5 ms
        try {
            skewed.next();
        } catch (IllegalStateException e) {
            System.out.println("refused: " + e.getMessage());
        }
        long[] fixed = {2_000_000L + EPOCH};             // same node id configured twice
        long a = new Snowflake(3, () -> fixed[0]).next();
        long b = new Snowflake(3, () -> fixed[0]).next();
        System.out.println("two generators with node id 3 produce the same id: " + (a == b));
    }
}

class LockService:
    def __init__(self):
        self.token = 0

    def acquire(self):
        self.token += 1
        return self.token                  # monotonically increasing fencing token


class Storage:
    def __init__(self, check_tokens):
        self.check, self.max_token, self.value = check_tokens, 0, None

    def write(self, who, token, value):
        if self.check and token < self.max_token:
            print(f"  {who}: write REJECTED (token {token} < {self.max_token})")
            return
        self.max_token, self.value = max(self.max_token, token), value
        print(f"  {who}: write accepted with token {token}")


def scenario(check):
    lock, store = LockService(), Storage(check)
    token_a = lock.acquire()               # client A holds the lock, then stalls (GC pause)
    token_b = lock.acquire()               # the lease expired; client B acquires the lock
    store.write("client B", token_b, "B-data")
    store.write("client A", token_a, "A-stale")   # A wakes up and still believes it holds the lock
    print(f"token check {'ON ' if check else 'OFF'}: final value = {store.value}")


