import random


def stale_read_rate(n, w, r, trials=20000, seed=3):
    rnd, stale = random.Random(seed), 0
    for _ in range(trials):
        replicas = [0] * n                           # version held by each replica
        for i in rnd.sample(range(n), w):            # a write just reached w replicas
            replicas[i] = 1
        if max(replicas[i] for i in rnd.sample(range(n), r)) == 0:
            stale += 1                               # no contacted replica had the new version
    return stale / trials


