import java.util.ArrayDeque;
import java.util.Deque;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.ArrayList;
import java.util.Map;
import java.util.Random;
import java.util.Set;

public class Delivery {
    record Msg(long id, String key, int amount) { }

    /** The broker redelivers every message that is not acknowledged (at-least-once).
     *  The consumer crashes with probability crashProb after the effect, before the ack. */
    static int[] run(boolean idempotent, double crashProb, long seed) {
        Random rnd = new Random(seed);
        Deque<Msg> queue = new ArrayDeque<>();
        for (int i = 0; i < 10_000; i++) queue.add(new Msg(i, "acct" + (i % 50), 1));
        Map<String, Integer> balance = new HashMap<>();
        Set<Long> processed = new HashSet<>();           // stands in for a processed_ids table
        int deliveries = 0, duplicatesApplied = 0;
        while (!queue.isEmpty()) {
            Msg m = queue.poll();
            deliveries++;
            boolean seen = processed.contains(m.id());
            if (!(idempotent && seen)) {
                balance.merge(m.key(), m.amount(), Integer::sum);     // the side effect
                if (seen) duplicatesApplied++;
                processed.add(m.id());
            }
            if (rnd.nextDouble() < crashProb) queue.addFirst(m);     // ack lost: redelivery
        }
        int total = balance.values().stream().mapToInt(Integer::intValue).sum();
        return new int[] {deliveries, duplicatesApplied, total};
    }

    public static void main(String[] args) {
        System.out.println("10,000 messages, each adds 1 to an account; expected total = 10000");
        System.out.println("probability of a crash between effect and ack: 2%");
        int[] a = run(false, 0.02, 11), b = run(true, 0.02, 11);
        System.out.printf("plain consumer     : deliveries=%d duplicates applied=%d total=%d%n",
                a[0], a[1], a[2]);
        System.out.printf("idempotent consumer: deliveries=%d duplicates applied=%d total=%d%n",
                b[0], b[1], b[2]);

        System.out.println("\nRetry delays: base 100 ms, factor 2, cap 5000 ms, full jitter");
        Random r = new Random(5);
        for (int attempt = 1; attempt <= 8; attempt++) {
            long ceiling = Math.min(5000, 100L * (1L << (attempt - 1)));
            System.out.printf("attempt %d: ceiling %4d ms, chosen delay %4d ms%n",
                    attempt, ceiling, (long) (r.nextDouble() * ceiling));
        }

        System.out.println("\nOrdering: 12 events, 3 keys, 3 partitions, hash(key) mod 3");
        List<List<String>> parts =
                List.of(new ArrayList<>(), new ArrayList<>(), new ArrayList<>());
        String[] keys = {"orderA", "orderB", "orderC"};
        for (int i = 0; i < 12; i++) {
            String k = keys[i % 3];
            parts.get(Math.floorMod(k.hashCode(), 3)).add(k + ":e" + (i / 3 + 1));
        }
        for (int p = 0; p < 3; p++) System.out.println("partition " + p + ": " + parts.get(p));
    }
}

"""Five rate limiting algorithms; limit = 100 requests per 10 s. Simulated time, no sleeping."""
import random
from collections import deque

LIMIT, WINDOW = 100, 10.0


class FixedWindow:
    def __init__(self):
        self.window, self.count = None, 0

    def allow(self, t):
        w = int(t // WINDOW)
        if w != self.window:
            self.window, self.count = w, 0
        if self.count < LIMIT:
            self.count += 1
            return True
        return False


class SlidingLog:
    def __init__(self):
        self.log = deque()

    def allow(self, t):
        while self.log and self.log[0] <= t - WINDOW:
            self.log.popleft()
        if len(self.log) < LIMIT:
            self.log.append(t)
            return True
        return False


class SlidingCounter:
    """Weights the previous window's count by the fraction of it still inside the sliding window."""
    def __init__(self):
        self.window, self.cur, self.prev = None, 0, 0

    def allow(self, t):
        w = int(t // WINDOW)
        if w != self.window:
            self.prev = self.cur if self.window == w - 1 else 0
            self.cur, self.window = 0, w
        estimate = self.prev * (1 - (t % WINDOW) / WINDOW) + self.cur
        if estimate < LIMIT:
            self.cur += 1
            return True
        return False


class TokenBucket:
    def __init__(self):
        self.tokens, self.last, self.rate = float(LIMIT), 0.0, LIMIT / WINDOW

    def allow(self, t):
        self.tokens = min(LIMIT, self.tokens + (t - self.last) * self.rate)
        self.last = t
        if self.tokens >= 1:
            self.tokens -= 1
            return True
        return False
class LeakyBucketMeter:
    """Bucket of capacity LIMIT that drains at LIMIT/WINDOW per second; a request adds one unit."""
    def __init__(self):
        self.level, self.last, self.rate = 0.0, 0.0, LIMIT / WINDOW

    def allow(self, t):
        self.level = max(0.0, self.level - (t - self.last) * self.rate)
        self.last = t
        if self.level + 1 <= LIMIT:
            self.level += 1
            return True
        return False


ALGOS = [("fixed window", FixedWindow), ("sliding log", SlidingLog),
         ("sliding counter", SlidingCounter), ("token bucket", TokenBucket),
         ("leaky bucket (meter)", LeakyBucketMeter)]

