import java.util.BitSet;
import java.util.Random;

public class BloomDemo {
    final BitSet bits;
    final int m, k;                                     // m bits, k hash functions

    BloomDemo(int m, int k) {
        this.m = m;
        this.k = k;
        this.bits = new BitSet(m);
    }

    static long mix(long x) {                           // 64-bit finaliser (MurmurHash3 style)
        x ^= x >>> 33; x *= 0xff51afd7ed558ccdL;
        x ^= x >>> 33; x *= 0xc4ceb9fe1a85ec53L;
        return x ^ (x >>> 33);
    }

    // double hashing: the i-th index is h1 + i * h2, which simulates k independent hashes
    private int index(long h1, long h2, int i) {
        return (int) Long.remainderUnsigned(h1 + i * h2, m);
    }

    void add(long key) {
        long h1 = mix(key), h2 = mix(key ^ 0x9e3779b97f4a7c15L) | 1;
        for (int i = 0; i < k; i++) bits.set(index(h1, h2, i));
    }

    boolean mightContain(long key) {
        long h1 = mix(key), h2 = mix(key ^ 0x9e3779b97f4a7c15L) | 1;
        for (int i = 0; i < k; i++) if (!bits.get(index(h1, h2, i))) return false;
        return true;
    }

    public static void main(String[] args) {
        int n = 1_000_000;
        System.out.println("n = 1,000,000 inserted keys; 1,000,000 probes of keys never inserted");
        System.out.println("bits/key  k | memory   | measured FPR | theory (1-e^(-kn/m))^k");
        for (int[] cfg : new int[][] {{5, 3}, {10, 7}, {15, 10}, {10, 3}}) {
            int bitsPerKey = cfg[0], k = cfg[1];
            BloomDemo f = new BloomDemo(n * bitsPerKey, k);
            for (long i = 0; i < n; i++) f.add(i);
            int falsePositives = 0, probes = 1_000_000;
            Random r = new Random(1);
            for (int i = 0; i < probes; i++) {
                if (f.mightContain(n + 1L + r.nextInt(Integer.MAX_VALUE))) falsePositives++;
            }
            double theory = Math.pow(1 - Math.exp(-(double) k * n / f.m), k);
            System.out.printf("%8d %2d | %.2f MiB | %.4f%%     | %.4f%%%n", bitsPerKey, k,
                    f.m / 8.0 / 1048576, 100.0 * falsePositives / probes, 100 * theory);
        }
    }
}

B32 = "0123456789bcdefghjkmnpqrstuvwxyz"


def geohash(lat, lon, chars=9):
    """Interleave longitude and latitude bisection bits (longitude first), 5 bits per character."""
    lat_r, lon_r, bits, even = [-90.0, 90.0], [-180.0, 180.0], [], True
    while len(bits) < chars * 5:
        rng, value = (lon_r, lon) if even else (lat_r, lat)
        mid = (rng[0] + rng[1]) / 2
        if value >= mid:
            bits.append(1)
            rng[0] = mid
        else:
            bits.append(0)
            rng[1] = mid
        even = not even
    return "".join(B32[int("".join(map(str, bits[i:i + 5])), 2)] for i in range(0, len(bits), 5))


